      <section id="view-list" class="view">
        <header class="head">
          <div class="head-top">
            <div>
              <h1>出货清单</h1>
              <p id="sub">连接中…</p>
            </div>
            <button class="icon-btn cloud-refresh" id="refresh" aria-label="刷新云表格" title="通知电脑检查云表格并获取最新清单">
              <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                <path d="M20 12a8 8 0 1 1-2.3-5.6" stroke-linecap="round" />
                <path d="M20 4v4h-4" stroke-linecap="round" stroke-linejoin="round" />
              </svg>
              <span>刷新云表格</span>
            </button>
          </div>

          <div class="mobile-toolbar">
            <div class="view-switch" id="layout-switch" aria-label="清单视图">
              <button data-layout="board" class="on">按票</button><button data-layout="table">全部明细</button>
            </div>
            <button class="export-entry" id="master-sync-open">同步详情</button><button class="export-entry" id="export-open">电脑同步</button>
          </div>

          <div class="stats">
            <div class="stat"><span>已出</span><b id="doneQty">0</b><i>件</i></div>
            <div class="stat"><span>未出</span><b id="leftQty">0</b><i>件</i></div>
            <div class="sync" id="sync">连接中</div>
          </div>

          <label class="search">
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
              <circle cx="11" cy="11" r="7" />
              <path d="M20 20l-3.5-3.5" stroke-linecap="round" />
            </svg>
            <input id="q" type="search" placeholder="搜单号 / 客户 / 商品" autocomplete="off" />
          </label>

          <div class="seg" id="seg">
            <button data-f="all" class="on">全部记录</button>
            <button data-f="todo">待出货</button>
            <button data-f="done">已出货</button>
            <button data-f="task">任务</button>
          </div>
        </header>

        <main id="tickets" class="list"></main>
      </section>

      <!-- 单据页 -->
      <section id="view-doc" class="view hidden">
        <div class="doc-bar">
          <button class="icon-btn" id="back" aria-label="返回">
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
              <path d="M15 5l-7 7 7 7" stroke-linecap="round" stroke-linejoin="round" />
            </svg>
          </button>
          <div class="doc-title">
            <div class="doc-no mono" id="docNo">—</div>
            <div class="doc-sub" id="docSub">—</div>
          </div>
          <span class="tag" id="docTag">—</span>
          <button class="export-entry" id="doc-export">同步 / 导出</button>
        </div>

        <div class="doc-head">
          <div class="prog-row">
            <div class="bar"><i id="docBar" style="width: 0"></i></div>
            <span id="docPct">0 / 0 行</span>
          </div>
          <div class="doc-stats">
            <span>已出 <b id="docDone">0</b> 件</span>
            <span>未出 <b id="docLeft">0</b> 件</span>
            <span class="diff" id="docDiff"></span>
          </div>
        </div>

        <label class="search doc-search">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
            <circle cx="11" cy="11" r="7" />
            <path d="M20 20l-3.5-3.5" stroke-linecap="round" />
          </svg>
          <input id="dq" type="search" placeholder="搜商品 / 入库号" autocomplete="off" />
        </label>

        <main id="lines" class="list lines"></main>

        <div class="doc-foot">
          <div class="foot-info">
            <b id="footDone">0</b><span> / </span><i id="footTotal">0</i><span> 件</span>
          </div>
          <button class="btn-primary" id="receive">确认出货</button>
        </div>
      </section>

      <section class="export-overlay hidden" id="export-panel" role="dialog" aria-modal="true" aria-labelledby="export-title">
        <div class="export-card">
          <div class="export-heading"><h2 id="export-title">电脑同步与备用导出</h2><button id="export-close" class="export-entry">关闭</button></div>
          <p id="export-sync-info" role="status" aria-live="polite"></p>
          <button class="btn-primary" id="export-sync">同步到当前电脑</button>
          <label for="export-scope">导出范围</label>
          <select id="export-scope">
            <option value="done">已出货明细</option>
            <option value="all">全部清单</option>
            <option value="ticket">当前票全部明细</option>
          </select>
          <p id="export-summary"></p>
          <textarea id="export-text" readonly aria-label="导出文本" spellcheck="false"></textarea>
          <p id="export-hint">复制后可通过微信发到电脑，再粘贴给助手核对记录。导出不会修改出货状态。</p>
          <button class="export-entry" id="export-copy">备用：复制全部文本</button>
        </div>
      </section>
      <section class="export-overlay hidden" id="row-copy-panel" role="dialog" aria-modal="true" aria-label="复制当前行"><div class="export-card"><div class="export-heading"><h2>复制当前行</h2><button id="row-copy-close">关闭</button></div><textarea id="row-copy-text" readonly aria-label="当前行复制内容"></textarea><p>自动复制未成功时，请长按文本复制。</p></div></section>
<section class="export-overlay hidden" id="row-edit-panel" role="dialog" aria-modal="true" aria-label="编辑明细"><div class="export-card"><div class="export-heading"><h2>记录单号</h2><button id="row-edit-close">取消</button></div><label>客户<input id="row-edit-customer" /></label><label>入库号<input id="row-edit-inbound" /></label><label>单号<input id="row-edit-waybill" /></label><label>特殊标注<select id="row-edit-special"><option value="">普通出货</option><option value="亚马逊">亚马逊</option><option value="发深圳">发深圳</option></select></label><p id="row-edit-error"></p><p>货物资料以云表为准；单号和出货状态保存在本地出货台账，手机与电脑双向同步，不修改云文档。</p><button id="row-edit-save" class="btn-primary">保存修改</button></div></section>
<section class="export-overlay hidden" id="master-sync-panel" role="dialog" aria-modal="true" aria-label="出货台账同步"><div class="export-card"><div class="export-heading"><h2>出货台账同步</h2><button id="master-sync-close">关闭</button></div><p id="master-sync-info"></p><button id="master-sync-now" class="btn-primary">同步完整出货台账</button><div id="master-conflicts"></div></div></section>
<div class="toast" id="toast" role="status"></div>
    </div>
    <script src="./transport.js"></script>
    <script src="./m.js"></script>
  </body>
</html>
","shipping/m.css":":root {
  --bg: #f1f3f5;
  --card: #fff;
  --line: rgba(15, 17, 21, 0.1);
  --line-2: rgba(15, 17, 21, 0.16);
  --text: #0f1115;
  --muted: #61666b;
  --faint: #81858c;
  --ok: #167a3c;
  --ok-bg: #f0fbf4;
  --warn: #8a5a0a;
  --warn-bg: #fff8e6;
  --font: "Segoe UI", "Microsoft YaHei UI", "PingFang SC", system-ui, sans-serif;
}
* {
  box-sizing: border-box;
  -webkit-tap-highlight-color: transparent;
}
html,
body {
  margin: 0;
  height: 100%;
  /* 整个页面不再滚动：交给 .list 自己滚，底部按钮和顶部栏就不会跟着动 */
  overflow: hidden;
}
body {
  background: var(--bg);
  color: var(--text);
  font: 14px/1.5 var(--font);
  -webkit-font-smoothing: antialiased;
  overscroll-behavior-y: none;
}
button {
  font: inherit;
  color: inherit;
  background: none;
  border: 0;
  padding: 0;
}
.mono {
  font-family: "SF Mono", "Cascadia Mono", Consolas, monospace;
  font-variant-numeric: tabular-nums;
}

.app {
  height: 100%;
  min-height: 0;
  display: flex;
  flex-direction: column;
}

/* 顶部：标题 + 统计 + 搜索 + 筛选 */
.head {
  position: sticky;
  top: 0;
  z-index: 20;
  padding: calc(10px + env(safe-area-inset-top)) 14px 8px;
  background: rgba(241, 243, 245, 0.94);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--line);
}
.head-top {
  display: flex;
  align-items: flex-start;
  gap: 10px;
}
h1 {
  margin: 0;
  font-size: 20px;
  font-weight: 600;
  letter-spacing: -0.2px;
}
#sub {
  margin: 2px 0 0;
  font-size: 12px;
  color: var(--muted);
}
.icon-btn {
  margin-left: auto;
  width: 34px;
  height: 34px;
  border-radius: 10px;
  background: #fff;
  border: 1px solid var(--line);
  display: grid;
  place-items: center;
  color: var(--muted);
}
.icon-btn svg {
  width: 17px;
  height: 17px;
}
.icon-btn:active {
  background: #ebeef2;
}

.stats {
  display: flex;
  align-items: baseline;
  gap: 16px;
  margin-top: 8px;
}
.stat {
  display: flex;
  align-items: baseline;
  gap: 4px;
  font-size: 12px;
  color: var(--muted);
}
.stat b {
  font-size: 19px;
  font-weight: 600;
  color: var(--text);
  font-variant-numeric: tabular-nums;
}
.stat i {
  font-style: normal;
  font-size: 11px;
  color: var(--faint);
}
.sync {
  margin-left: auto;
  font-size: 11px;
  color: var(--muted);
}
.sync.err {
  color: #b32d2d;
}

.search {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-top: 10px;
  height: 36px;
  padding: 0 10px;
  border-radius: 9px;
  background: #fff;
  border: 1px solid var(--line-2);
}
.search svg {
  width: 15px;
  height: 15px;
  color: var(--faint);
  flex: none;
}
.search input {
  flex: 1;
  min-width: 0;
  border: 0;
  outline: 0;
  background: none;
  font: inherit;
  font-size: 14px;
}
.search input::-webkit-search-cancel-button {
  display: none;
}

.chips {
  display: flex;
  gap: 6px;
  overflow-x: auto;
  padding: 9px 0 2px;
  scrollbar-width: none;
}
.chips::-webkit-scrollbar {
  display: none;
}
.chip {
  flex: none;
  padding: 5px 10px;
  border-radius: 999px;
  border: 1px solid var(--line);
  background: #fff;
  color: var(--muted);
  font-size: 11.5px;
  white-space: nowrap;
}
.chip b {
  color: var(--text);
  font-weight: 600;
  margin-left: 4px;
  font-variant-numeric: tabular-nums;
}
.chip.on {
  background: var(--text);
  border-color: var(--text);
  color: rgba(255, 255, 255, 0.72);
}
.chip.on b {
  color: #fff;
}

.seg {
  display: flex;
  gap: 2px;
  margin-top: 9px;
  padding: 2px;
  border-radius: 9px;
  background: #ebeef2;
}
.seg button {
  flex: 1;
  height: 30px;
  border-radius: 7px;
  font-size: 12.5px;
  color: var(--muted);
}
.seg button.on {
  background: #fff;
  color: var(--text);
  font-weight: 600;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.08);
}

/* 列表 */
.list {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
  overscroll-behavior: contain;
  /* 底部多留 44px：外壳右下角的设置齿轮会压住最后一张票 */
  padding: 10px 12px calc(72px + env(safe-area-inset-bottom));
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.row {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 12px;
  border-radius: 11px;
  background: var(--card);
  border: 1px solid var(--line);
  content-visibility: auto;
  contain-intrinsic-size: auto 46px;
  transition: background 0.12s, border-color 0.12s;
}
.row:active {
  background: #f7f8f9;
}
.row.done {
  background: #fbfcfd;
}
.tick {
  flex: none;
  width: 26px;
  height: 26px;
  border-radius: 8px;
  border: 1px solid var(--line-2);
  background: #fff;
  display: grid;
  place-items: center;
  color: transparent;
}
.tick svg {
  width: 15px;
  height: 15px;
}
/* 没入库号也没单号：灰着、勾不动（照常算未出、照常出现在票里） */
.row.blocked .tick {
  opacity: 0.4;
  cursor: not-allowed;
}
.row.blocked .name {
  color: var(--muted, #98a1ad);
}
.row.done .tick {
  background: var(--text);
  border-color: var(--text);
  color: #fff;
}
.body {
  flex: 1;
  min-width: 0;
  /* 名称 / 入库号·客户 / 标签 全排成一行（2026-11-01 用户要求） */
  display: flex;
  align-items: center;
  gap: 8px;
}
.cust {
  flex: none;
  max-width: 62px;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
  font-size: 12.5px;
  color: var(--muted);
}
.name {
  font-size: 13.5px;
  font-weight: 600;
  line-height: 1.35;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
  flex: 1 1 auto;
  min-width: 0;
}
.mono.inb {
  flex: none;
  font-size: 10.5px;
  color: var(--muted);
  white-space: nowrap;
}
.row.done .name {
  color: var(--muted);
  font-weight: 500;
}
.meta {
  display: flex;
  align-items: center;
  gap: 5px;
  flex: 1 1 auto;
  min-width: 0;
  font-size: 11px;
  color: var(--muted);
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}
.meta .mono {
  font-size: 10.5px;
  color: var(--muted);
}
.meta .dot {
  width: 3px;
  height: 3px;
  border-radius: 50%;
  background: #d5d9df;
  flex: none;
}
.tag {
  display: inline-block;
  margin-top: 0;
  flex: none;
  padding: 0 6px;
  border-radius: 5px;
  background: var(--warn-bg);
  color: var(--warn);
  font-size: 10.5px;
  line-height: 17px;
}
.qty {
  flex: none;
  text-align: right;
