    var issues = list.filter(hasProblem).length;
    return {
      total: total,
      done: done,
      left: total - done,
      n: list.length,
      doneRows: doneRows,
      issues: issues,
      pct: total ? Math.round((done / total) * 100) : 0,
      status: done === total && total > 0 ? "done" : doneRows > 0 ? "part" : "todo",
