      if (keyOf(rows[i]) === k) {
        r = rows[i];
        break;
      }
    }
    if (!r || saving[k]) return;
    if (!r.checked && !isAmazon(r) && (!String(r.waybill || "").trim() || !String(r.inbound || "").trim())) { toast("入库号和单号必须都填写，才能出货"); return; }
