        delete saving[k];
        updateDocNumbers();
      });
  }

  function receive() {
    if(receiving||Object.keys(saving).length)return;
    var list = docRows();
    var pending = list.filter(function (r) {
      return !r.checked && !r.blocked && (isAmazon(r) || (String(r.waybill || "").trim() && String(r.inbound || "").trim())); // 没入库号/单号的跳过，勾不动
